import XCTest

final class TapTests: XCTestCase {
    func testOpenSearchTab() {
        let harnessDir = "/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/harness"

        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let openBtn = springboard.buttons["Open"]
        if openBtn.waitForExistence(timeout: 5) {
            openBtn.tap()
            Thread.sleep(forTimeInterval: 2)
        }

        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()

        func dumpHierarchy(_ tag: String) {
            try? app.debugDescription.write(toFile: "\(harnessDir)/hierarchy_\(tag).txt", atomically: true, encoding: .utf8)
        }

        func isOnSearch() -> Bool {
            return app.textFields["Search"].exists || app.staticTexts["Explore"].exists
        }

        if !isOnSearch() {
            let searchBtn = app.buttons["Search"]
            if searchBtn.waitForExistence(timeout: 15) {
                searchBtn.tap()
            } else {
                dumpHierarchy("precoord")
                let coord = app.coordinate(withNormalizedOffset: CGVector(dx: 0.314, dy: 0.964))
                coord.tap()
            }
        }

        Thread.sleep(forTimeInterval: 3)
        dumpHierarchy("final")
        XCTAssertTrue(isOnSearch(), "did not reach Search/Explore tab")
    }
}
